using SixLabors.ImageSharp.Formats.Av1.Prediction;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates the compound (multi-reference) inter prediction: the 16-bit prep convolution combined by
/// average, weighted-average and mask blending, against dav1d's prep_8tap + avg/w_avg/mask for two 8x8
/// predictions gathered from a 40x40 reference with distinct motion vectors.
/// </summary>
public class Av1CompoundPredictionTests
{
    private const int W = 8;
    private const int H = 8;

    private static (short[] T1, short[] T2) Prep()
    {
        short[] t1 = new short[W * H];
        short[] t2 = new short[W * H];
        Av1Convolve.PrepBlock(t1, Ref, 40, 40, 40, 5, 5, W, H, 4, 6, 0);
        Av1Convolve.PrepBlock(t2, Ref, 40, 40, 40, 10, 8, W, H, 2, 0, 1);
        return (t1, t2);
    }

    [Fact]
    public void Average_MatchesDav1d()
    {
        (short[] t1, short[] t2) = Prep();
        ushort[] dst = new ushort[W * H];
        Av1Convolve.Average(dst, 0, W, t1, t2, W, H);
        Assert.Equal(new ushort[] { 108, 40, 45, 145, 157, 151, 148, 118, 91, 113, 99, 204, 189, 196, 193, 134, 81, 155, 94, 172, 149, 118, 129, 79, 116, 179, 97, 157, 153, 118, 81, 115, 112, 149, 169, 179, 77, 79, 98, 135, 168, 159, 154, 115, 80, 115, 119, 88, 99, 83, 84, 50, 72, 169, 152, 131, 161, 110, 121, 80, 57, 90, 93, 187 }, dst);
    }

    [Fact]
    public void WeightedAverage_MatchesDav1d()
    {
        (short[] t1, short[] t2) = Prep();
        ushort[] dst = new ushort[W * H];
        Av1Convolve.WeightedAverage(dst, 0, W, t1, t2, W, H, 5);
        Assert.Equal(new ushort[] { 120, 54, 44, 120, 164, 174, 160, 131, 79, 97, 111, 197, 193, 185, 176, 131, 71, 135, 112, 176, 155, 113, 122, 109, 133, 170, 98, 148, 152, 117, 102, 127, 99, 135, 167, 182, 105, 94, 111, 118, 160, 150, 149, 136, 102, 106, 108, 95, 87, 88, 94, 63, 80, 160, 158, 149, 152, 134, 122, 72, 55, 78, 92, 185 }, dst);
    }

    [Fact]
    public void Mask_MatchesDav1d()
    {
        (short[] t1, short[] t2) = Prep();
        ushort[] dst = new ushort[W * H];
        Av1Convolve.Mask(dst, 0, W, t1, t2, Msk, W, H);
